function normalizeData(saved={}){const {activeDay,musicUrl,...state}=saved||{},catalog=(Array.isArray(saved.catalog)?saved.catalog:structuredClone(seed.catalog)).map(item=>{const {rest,...entry}=item;return {...entry,group:muscleGroups.includes(entry.group)?entry.group:'Sonstige'}}),plan=(Array.isArray(saved.plan)?saved.plan:structuredClone(seed.plan)).map(({day,...w})=>({...w,exercises:(w.exercises||[]).map(({rest,...exercise})=>exercise)}));return {...structuredClone(seed),...state,catalog,plan,history:Array.isArray(saved.history)?saved.history:[]}}
