function updateCloudButton(){const button=$('#cloudBtn'),sync=$('#syncBtn'),check=$('#cloudCheck'),mark=$('#profileMark'),connected=Boolean(cloudUser);if(mark){mark.textContent=connected?(activeProfileName||'Carsten').trim().charAt(0).toUpperCase():'?';mark.title=connected?`Profil ${activeProfileName||'verbunden'}`:'Zum Anmelden';mark.setAttribute('aria-label',connected?`Profil ${activeProfileName||'verbunden'}`:'Anmelden');}if(check)check.hidden=!connected;if(sync){sync.classList.toggle('sync-connected',connected);sync.title=connected?`Jetzt mit der Cloud synchronisieren · ${activeProfileName||cloudUser.email||'angemeldet'}`:'Anmelden und synchronisieren';sync.setAttribute('aria-label',sync.title)}if(button){button.title='Settings öffnen';button.setAttribute('aria-label',button.title)}}
async function startCloud(){const config=storedCloudConfig();if(!config.url||!config.key||!window.supabase?.createClient){updateCloudButton();return}try{createCloudClient(config);const {data:result,error}=await cloudClient.auth.getSession();if(error)throw error;const user=result.session?.user;if(user)await activateCloudUser(user,null);updateCloudButton()}catch(error){console.warn('Cloud-Verbindung konnte nicht gestartet werden:',error.message);updateCloudButton()}}
async function cloudFetch(){const {data:row,error}=await cloudClient.from('fitness_data').select('payload,version,updated_at').eq('user_id',cloudUser.id).maybeSingle();if(error)throw error;return row}
function applyCloudRow(row){const incoming=row.payload;if(!isValidFitnessData(incoming))throw Error('Die Cloud-Sicherung enthält kein gültiges GrevingFit-Datenformat.');data=normalizeData(incoming);localStorage.setItem(KEY,JSON.stringify(data));localStorage.setItem(`${KEY}:${cloudUser.id}`,JSON.stringify(data));cloudVersion=Number(row.version);localStorage.setItem(CLOUD_VERSION_KEY,String(cloudVersion));localStorage.setItem(CLOUD_OWNER_KEY,cloudUser.id);localStorage.removeItem(CLOUD_DIRTY_KEY);render();updateCloudButton()}
async function cloudWrite(payload,expectedVersion=null){const now=new Date().toISOString(),values={payload:structuredClone(payload),version:(expectedVersion||0)+1,updated_at:now};let query;if(expectedVersion===null)query=cloudClient.from('fitness_data').insert({user_id:cloudUser.id,...values});else query=cloudClient.from('fitness_data').update(values).eq('user_id',cloudUser.id).eq('version',expectedVersion);const {data:rows,error}=await query.select('version,updated_at').maybeSingle();if(error)throw error;if(!rows)return null;cloudVersion=Number(rows.version);localStorage.setItem(CLOUD_VERSION_KEY,String(cloudVersion));localStorage.setItem(CLOUD_OWNER_KEY,cloudUser.id);localStorage.setItem(`${KEY}:${cloudUser.id}`,JSON.stringify(data));localStorage.removeItem(CLOUD_DIRTY_KEY);updateCloudButton();return rows}
async function cloudInitialSync(){if(!cloudClient||!cloudUser||!activeProfileName)return;cloudReady=false;try{const row=await cloudFetch(),owner=localStorage.getItem(CLOUD_OWNER_KEY),sameAccount=owner===cloudUser.id;if(!row){if(owner&&!sameAccount&&!localStorage.getItem(`${KEY}:${cloudUser.id}`)){showEmptyCloudChoices();return}const inserted=await cloudWrite(data,null);if(!inserted)throw Error('Die erste Cloud-Sicherung konnte nicht erstellt werden.');cloudReady=true;toast('Lokale Daten erstmals in der Cloud gesichert');return}const dirty=localStorage.getItem(CLOUD_DIRTY_KEY)==='1';if(!sameAccount||dirty){showCloudChoices(row,!sameAccount?'Diese Cloud enthält bereits Daten. Wähle die Version für '+activeProfileName+'.':'Auf diesem Gerät gibt es noch nicht synchronisierte Änderungen. Wähle die Version, die gelten soll.');return}if(cloudVersion!==Number(row.version)){showCloudChoices(row,'Neuere Cloud-Daten für '+activeProfileName+' sind verfügbar. Möchtest du sie auf dieses Gerät laden?');return}updateCloudButton();cloudReady=true}catch(error){console.error('Cloud-Synchronisierung fehlgeschlagen:',error);toast(`Cloud-Sync fehlgeschlagen: ${error.message||'Verbindung prüfen'}`)}}
function stopCloudWatch(){if(cloudPollTimer){clearInterval(cloudPollTimer);cloudPollTimer=0}}
async function checkCloudForUpdates(){if(!cloudClient||!cloudUser||!activeProfileName||cloudCheckBusy||document.visibilityState==='hidden')return;cloudCheckBusy=true;try{const row=await cloudFetch();if(!row||Number(row.version)<=Number(cloudVersion||0)||Number(row.version)===cloudDeferredVersion)return;const dialog=$('#modal');if(dialog?.open)return;cloudReady=false;const dirty=localStorage.getItem(CLOUD_DIRTY_KEY)==='1';showCloudChoices(row,dirty?'Neuere Cloud-Daten sind verfügbar. Auf diesem Gerät gibt es außerdem noch nicht synchronisierte Änderungen. Wähle, welche Version gelten soll.':'Neuere Cloud-Daten für '+activeProfileName+' sind verfügbar. Möchtest du sie auf dieses Gerät laden?')}catch(error){console.warn('Cloud-Änderungen konnten nicht geprüft werden:',error.message)}finally{cloudCheckBusy=false}}
function startCloudWatch(){stopCloudWatch();if(!cloudClient||!cloudUser)return;cloudPollTimer=setInterval(checkCloudForUpdates,5000)}
async function cloudSaveNow(){if(!cloudClient||!cloudUser||!cloudReady||cloudSaving||localStorage.getItem(CLOUD_DIRTY_KEY)!=='1')return;cloudSaving=true;try{const saved=await cloudWrite(data,cloudVersion);if(!saved){toast('Cloud-Konflikt: Öffne ☁ und wähle die gewünschte Version.');return}toast('Änderungen in der Cloud gespeichert')}catch(error){console.error('Cloud-Speichern fehlgeschlagen:',error);toast('Cloud-Speichern fehlgeschlagen – lokal bleibt alles erhalten')}finally{cloudSaving=false}}
function showCloudChoices(row,message){const existing=$('#modal');if(existing?.open&&existing.dataset.cloudVersion===String(row.version))return;const d=modal(`<h2>Cloud-Daten abgleichen</h2><p>${esc(message)}</p><p class="tiny muted">Cloud-Stand: ${new Date(row.updated_at).toLocaleString('de-DE')}</p><div class="grid"><button class="button" type="button" data-cloud-load>Cloud-Daten auf dieses Gerät laden</button><button class="button secondary" type="button" data-cloud-overwrite>Lokale Daten in die Cloud übernehmen</button><button class="button ghost" type="button" data-close>Später entscheiden</button></div>`);d.dataset.cloudVersion=String(row.version);$('[data-cloud-load]',d).onclick=()=>{try{cloudDeferredVersion=null;applyCloudRow(row);cloudReady=true;d.close();toast('Cloud-Daten geladen')}catch(error){alert(error.message)}};$('[data-cloud-overwrite]',d).onclick=async()=>{try{const saved=await cloudWrite(data,Number(row.version));if(!saved){d.close();showCloudChoices(await cloudFetch(),'Die Cloud wurde zwischenzeitlich geändert. Bitte wähle erneut.');return}cloudReady=true;d.close();toast('Lokale Daten gespeichert')}catch(error){alert(`Cloud-Speichern fehlgeschlagen: ${error.message}`)}};$('[data-close]',d).onclick=()=>{d.close();cloudDeferredVersion=Number(row.version);cloudReady=false}}
function profileSelectMarkup(selected=''){return `<div class="field"><label for="profileName">Profil</label><select id="profileName" name="profileName"><option value="">Profil auswählen …</option>${familyProfiles.map(name=>`<option value="${name}" ${name===selected?'selected':''}>${name}</option>`).join('')}</select></div>`}
async function claimCloudProfile(name){if(!familyProfiles.includes(name))throw Error('Bitte wähle eines der vier Profile.');if(!profileEmailMatches(name,cloudUser?.email))throw Error(`Für ${name} ist ausschließlich ${profileEmails[name]||'die festgelegte E-Mail-Adresse'} zugelassen.`);const {data:profile,error}=await cloudClient.from('fitness_profiles').insert({user_id:cloudUser.id,display_name:name}).select('display_name').single();if(error)throw Error(error.code==='23505'?'Dieses Profil ist bereits vergeben. Bitte wähle ein anderes.':error.message);activeProfileName=profile.display_name;localStorage.setItem(`grevingfit-profile:${cloudUser.id}`,activeProfileName);localStorage.setItem(ACTIVE_PROFILE_KEY,activeProfileName);render();updateCloudButton()}
async function ensureCloudProfile(requestedName=null){const {data:profile,error}=await cloudClient.from('fitness_profiles').select('display_name').eq('user_id',cloudUser.id).maybeSingle();if(error)throw error;if(profile){if(!profileEmailMatches(profile.display_name,cloudUser.email))throw Error(`Dieses Konto passt nicht zum Profil ${profile.display_name}.`);activeProfileName=profile.display_name;localStorage.setItem(`grevingfit-profile:${cloudUser.id}`,activeProfileName);localStorage.setItem(ACTIVE_PROFILE_KEY,activeProfileName);return true}if(requestedName){await claimCloudProfile(requestedName);return true}showProfileClaimModal();return false}
