function statsWeekStart(date){const start=new Date(date);start.setHours(0,0,0,0);start.setDate(start.getDate()-((start.getDay()+6)%7));return start}
function localDateKey(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function statsWeekKey(date){return localDateKey(statsWeekStart(new Date(`${date}T12:00:00`)))}
function statsValueLabel(value,unit){return `${Number(value).toLocaleString('de-DE',{maximumFractionDigits:1})} ${unit}`}
function hasSetMeasurement(set){return ['weight','reps','seconds'].some(key=>set[key]!==''&&set[key]!=null&&String(set[key]).trim()!=='')}
function exerciseProgress(sessions,name){const matching=sessions.flatMap(session=>performedExercises(session).filter(exercise=>exercise.name===name).map(exercise=>({session,exercise}))),allSets=matching.flatMap(item=>item.exercise.sets||[]),mode=allSets.some(set=>statsNumber(set.weight)>0)?'Gewicht':allSets.some(set=>statsNumber(set.seconds)>0)?'Haltezeit':'Wiederholungen',field=mode==='Gewicht'?'weight':mode==='Haltezeit'?'seconds':'reps',points=[];matching.sort((a,b)=>a.session.date.localeCompare(b.session.date)).forEach(({session,exercise})=>{const sets=exercise.sets||[],values=sets.map(set=>statsNumber(set[field])).filter(value=>value>0);if(!values.length)return;const value=Math.max(...values),top=sets.filter(set=>statsNumber(set[field])===value),repsAtTop=Math.max(0,...top.map(set=>statsNumber(set.reps)));points.push({name,date:session.date,value,mode,reps:repsAtTop,sets:sets.length})});return points}
function progressChartSvg(points,unit){if(!points.length)return `<div class="empty"><strong>Noch keine messbaren Satzwerte</strong><p>Gewicht, Wiederholungen oder Sekunden werden hier im Verlauf angezeigt.</p></div>`;let values=points.map(point=>point.value),min=Math.min(...values),max=Math.max(...values),ticks;if(unit==='kg'){const rawRange=Math.max(2.5,max-min),step=Math.max(2.5,Math.ceil(rawRange/5/2.5)*2.5);min=Math.max(0,Math.floor(min/step)*step);max=Math.ceil(max/step)*step;if(min===max){min=Math.max(0,min-step);max+=step}ticks=Array.from({length:Math.round((max-min)/step)+1},(_,index)=>max-index*step)}else{if(min===max){const scalePad=Math.max(1,max*.08);min=Math.max(0,min-scalePad);max+=scalePad}else{const scalePad=(max-min)*.12;min=Math.max(0,min-scalePad);max+=scalePad}ticks=[max,(max+min)/2,min]}const mobile=innerWidth<=650,w=mobile?360:720,pad={l:mobile?58:70,r:mobile?14:20,t:24,b:42},h=unit==='kg'?Math.max(230,ticks.length*30+pad.t+pad.b):230,x=i=>pad.l+(points.length===1?(w-pad.l-pad.r)/2:i*(w-pad.l-pad.r)/(points.length-1)),y=value=>pad.t+(max-value)*(h-pad.t-pad.b)/(max-min),coords=points.map((point,i)=>`${x(i)},${y(point.value)}`).join(' ');return `<div class="chart-wrap progress-chart-wrap" style="height:${h}px"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(points[0].mode)}-Fortschritt für ${esc(points[0].name||'Übung')}">${ticks.map((tick,index)=>`<line class="chart-grid" x1="${pad.l}" y1="${y(tick)}" x2="${w-pad.r}" y2="${y(tick)}"/><text class="chart-label" x="0" y="${y(tick)+4}">${esc(statsValueLabel(tick,unit))}</text>`).join('')}<polyline class="chart-line" points="${coords}"/>${points.map((point,i)=>`<circle class="chart-dot" cx="${x(i)}" cy="${y(point.value)}" r="5"><title>${formatDate(point.date)} · ${statsValueLabel(point.value,unit)}${point.reps?` · ${point.reps} Wdh.`:''}</title></circle>`).join('')}<text class="chart-label" x="${pad.l}" y="${h-6}">${formatDate(points[0].date,{day:'numeric',month:'short'})}</text><text class="chart-label" text-anchor="end" x="${w-pad.r}" y="${h-6}">${formatDate(points.at(-1).date,{day:'numeric',month:'short'})}</text></svg></div>`}
function weeklyVolumeChart(sessions){const now=new Date(),current=statsWeekStart(now),weeks=Array.from({length:8},(_,index)=>{const start=new Date(current);start.setDate(start.getDate()-(7*(7-index)));const key=localDateKey(start);return {key,start,total:0,count:0}}),byKey=new Map(weeks.map(week=>[week.key,week]));sessions.forEach(session=>{const week=byKey.get(statsWeekKey(session.date));if(week){week.total+=volume(session);week.count++}});const max=Math.max(1,...weeks.map(week=>week.total)),w=innerWidth<=650?360:720,h=220,pad={l:12,r:12,t:28,b:38},bar=(w-pad.l-pad.r)/8;return `<div class="chart-wrap volume-chart-wrap"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Trainingsvolumen pro Woche der letzten acht Wochen">${weeks.map((week,index)=>{const height=week.total?Math.max(5,(h-pad.t-pad.b)*week.total/max):3,x=pad.l+index*bar+bar*.18,y=h-pad.b-height;return `<rect x="${x}" y="${y}" width="${bar*.64}" height="${height}" rx="7" fill="var(--lime)"><title>${formatDate(week.key,{day:'numeric',month:'short'})} · ${Math.round(week.total).toLocaleString('de-DE')} kg · ${week.count} Einheiten</title></rect><text class="chart-label" text-anchor="middle" x="${pad.l+index*bar+bar/2}" y="${h-10}">${week.start.toLocaleDateString('de-DE',innerWidth<=650?{day:'2-digit',month:'2-digit'}:{day:'numeric',month:'short'})}</text>${week.total?`<text class="chart-label" text-anchor="middle" x="${pad.l+index*bar+bar/2}" y="${Math.max(12,y-7)}">${week.total>=1000?`${(Math.round(week.total/100)/10).toLocaleString('de-DE')}k`:Math.round(week.total).toLocaleString('de-DE')}</text>`:''}`}).join('')}</svg></div>`}
function muscleGroupStats(sessions){const groups=new Map(),catalog=new Map((data.catalog||[]).map(item=>[item.name,item.group||'Sonstige']));sessions.forEach(session=>performedExercises(session).forEach(exercise=>{const sets=(exercise.sets||[]).filter(hasSetMeasurement).length;if(!sets)return;const group=catalog.get(exercise.name)||'Sonstige';groups.set(group,(groups.get(group)||0)+sets)}));return [...groups].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0],'de'))}
function renderStats(){const sessions=workouts(),names=[...new Set(sessions.flatMap(session=>performedExercises(session).map(exercise=>exercise.name)))].sort((a,b)=>{const groupA=catalogItem(a)?.group||'Sonstige',groupB=catalogItem(b)?.group||'Sonstige';if(groupA==='Sonstige'&&groupB!=='Sonstige')return 1;if(groupB==='Sonstige'&&groupA!=='Sonstige')return -1;return groupA.localeCompare(groupB,'de',{sensitivity:'base'})||a.localeCompare(b,'de',{sensitivity:'base'})}),params=new URLSearchParams(location.hash.split('?')[1]||''),selected=params.get('exercise')||names[0]||'',now=new Date(),thirtyDays=new Date(now);thirtyDays.setDate(thirtyDays.getDate()-29);thirtyDays.setHours(0,0,0,0);const recent=sessions.filter(session=>new Date(`${session.date}T12:00:00`)>=thirtyDays&&session.date<=localDateKey(now)),recentVolume=recent.reduce((sum,session)=>sum+volume(session),0),loggedSets=sessions.reduce((sum,session)=>sum+performedExercises(session).reduce((n,exercise)=>n+(exercise.sets||[]).filter(hasSetMeasurement).length,0),0),weekKeys=new Set(sessions.map(session=>statsWeekKey(session.date))),thisWeekKey=localDateKey(statsWeekStart(now));let streak=0,weekCursor=new Date(statsWeekStart(now));if(!weekKeys.has(thisWeekKey))weekCursor.setDate(weekCursor.getDate()-7);while(weekKeys.has(localDateKey(weekCursor))){streak++;weekCursor.setDate(weekCursor.getDate()-7)}const points=selected?exerciseProgress(sessions,selected):[],mode=points[0]?.mode||'Gewicht',unit=mode==='Gewicht'?'kg':mode==='Haltezeit'?'Sek.':'Wdh.',best=points.length?Math.max(...points.map(point=>point.value)):0,first=points[0]?.value||0,last=points.at(-1)?.value||0,delta=first&&points.length>1?((last-first)/first)*100:null,groups=muscleGroupStats(sessions),maxGroup=Math.max(1,...groups.map(([,count])=>count));let summaryLabel=mode==='Gewicht'?'Schwerster Satz':mode==='Haltezeit'?'Längste Haltezeit':'Meiste Wiederholungen';return `<div class="eyebrow">DEIN FORTSCHRITT</div><div class="heading-row"><div><h1>Deine Auswertung</h1></div></div><div class="grid stats-kpis"><div class="metric"><div class="metric-label">Einheiten · 30 Tage</div><div class="metric-value">${recent.length}</div><div class="metric-note">${sessions.length} insgesamt</div></div><div class="metric"><div class="metric-label">Volumen · 30 Tage</div><div class="metric-value">${Math.round(recentVolume).toLocaleString('de-DE')} <small>kg</small></div><div class="metric-note">Gewicht × Wiederholungen</div></div><div class="metric"><div class="metric-label">Trainingsserie</div><div class="metric-value">${streak} <small>${streak===1?'Woche':'Wochen'}</small></div><div class="metric-note">aufeinanderfolgend</div></div><div class="metric"><div class="metric-label">Arbeitssätze</div><div class="metric-value">${loggedSets}</div><div class="metric-note">mit erfassten Werten</div></div></div><section class="card stats-section"><div class="card-head"><div><h2>Trainingsvolumen</h2><p class="tiny muted">Gewichtete Wiederholungen je Woche · letzte 8 Wochen</p></div></div>${recentVolume>0||sessions.some(session=>volume(session)>0)?weeklyVolumeChart(sessions):`<div class="empty">Hier erscheint dein wöchentliches Volumen, sobald du Gewicht und Wiederholungen protokollierst.</div>`}</section><section class="card stats-section"><div class="card-head stats-exercise-head"><div><h2>Übungsfortschritt</h2><p class="tiny muted">Vergleiche deinen stärksten Satz je Training.</p></div>${names.length?`<label class="stats-select-label"><span class="sr-only">Übung auswählen</span><select data-stats-exercise aria-label="Übung für Fortschritt auswählen">${names.map(name=>`<option value="${esc(name)}" ${name===selected?'selected':''}>${esc(catalogItem(name)?.group||'Sonstige')} - ${esc(name)}</option>`).join('')}</select></label>`:''}</div>${selected?`${progressChartSvg(points,unit)}${points.length?`<div class="stats-records"><div class="stats-record"><span>${summaryLabel}</span><strong>${statsValueLabel(best,unit)}</strong></div><div class="stats-record"><span>Letzter Eintrag</span><strong>${statsValueLabel(last,unit)}</strong></div><div class="stats-record"><span>Veränderung</span><strong class="${delta===null?'':delta>=0?'positive':'negative'}">${delta===null?'Noch keine Vergleichswerte':`${delta>=0?'+':''}${delta.toLocaleString('de-DE',{maximumFractionDigits:1})}% seit Start`}</strong></div></div><p class="tiny muted stats-footnote">${points.length} Einheiten mit Messwert · ${mode==='Gewicht'?'Punkte zeigen das höchste Gewicht pro Einheit.':'Ohne Gewichtseintrag zeigt das Diagramm Wiederholungen oder Haltezeit.'}</p>`:''}`:`<div class="empty">Füge Übungen zu einem gespeicherten Training hinzu, um Fortschritte zu vergleichen.</div>`}</section><section class="grid stats-lower"><div class="card stats-section"><div class="card-head"><div><h2>Trainierte Muskelgruppen</h2><p class="tiny muted">Arbeitssätze im gesamten Verlauf</p></div></div>${groups.length?`<div class="group-breakdown">${groups.map(([group,count])=>`<div class="group-stat"><div><span>${esc(group)}</span><strong>${count}</strong></div><div class="group-track"><i style="width:${Math.max(5,count/maxGroup*100)}%"></i></div></div>`).join('')}</div>`:`<div class="empty">Noch keine Satzdaten vorhanden.</div>`}</div><div class="card stats-section"><div class="card-head"><div><h2>Zuletzt trainiert</h2><p class="tiny muted">Deine letzten Einheiten</p></div><a href="#history" class="tiny muted">Zum Verlauf →</a></div>${sessions.length?`<div class="stats-recent">${sessions.slice(0,5).map(session=>`<div class="stats-recent-row"><div><strong>${esc(session.name)}</strong><span>${formatDate(session.date,{day:'numeric',month:'short',year:'numeric'})}</span></div><div><b>${performedExercises(session).length}</b><span>Übungen</span></div><div><b>${Math.round(volume(session)).toLocaleString('de-DE')}</b><span>kg Volumen</span></div></div>`).join('')}</div>`:`<div class="empty">Deine gespeicherten Trainingseinheiten erscheinen hier.</div>`}</div></section>`}
function bind(){$$('[data-exercise-status]').forEach(el=>el.onclick=()=>setSessionExerciseStatus(+el.dataset.exerciseIndex,el.dataset.exerciseStatus));$$('[data-start]').forEach(el=>el.onclick=()=>beginTemplateSession(el.dataset.start));$$('[data-action="free-session"]').forEach(el=>el.onclick=startFreeSession);$$('[data-action="resume-session"]').forEach(el=>el.onclick=()=>{sessionDraft=loadSessionDraft()||sessionDraft;location.hash=resumeSessionRoute()});$$('[data-action="discard-session-draft"]').forEach(el=>el.onclick=()=>{if(confirm('Zwischengespeichertes Training löschen?')){sessionDraft=null;persistSessionDraft();render()}});$$('[data-action="save-session-draft"]').forEach(el=>el.onclick=()=>{persistSessionDraft();location.hash='#home';toast('Training zwischengespeichert')});$$('[data-action="free-add-exercise"]').forEach(el=>el.onclick=freeExerciseDialog);$$('[data-free-set-change]').forEach(el=>el.onclick=()=>{const [index,delta]=el.dataset.freeSetChange.split(':').map(Number),exercise=sessionDraft?.exercises[index];if(!exercise)return;exercise.sets=Math.max(1,Math.min(20,(+exercise.sets||1)+delta));persistSessionDraft();render()});$$('[data-free-exercise-delete]').forEach(el=>el.onclick=()=>{const index=+el.dataset.freeExerciseDelete;if(!sessionDraft?.exercises[index])return;if(confirm(`„${sessionDraft.exercises[index].name}“ aus diesem Training entfernen?`)){sessionDraft.exercises.splice(index,1);persistSessionDraft();render()}});$$('[data-action="new-workout"]').forEach(el=>el.onclick=()=>workoutDialog());$$('[data-edit-workout]').forEach(el=>el.onclick=()=>workoutDialog(data.plan.find(w=>w.id===el.dataset.editWorkout)));$$('[data-delete-workout]').forEach(el=>el.onclick=()=>{if(confirm('Diese Vorlage löschen?')){data.plan=data.plan.filter(w=>w.id!==el.dataset.deleteWorkout);save();render()}});$$('[data-add-exercise]').forEach(el=>el.onclick=()=>exerciseDialog(el.dataset.addExercise));$$('[data-edit-exercise]').forEach(el=>el.onclick=()=>{const [id,index]=el.dataset.editExercise.split(':');exerciseDialog(id,+index)});$$('[data-delete-exercise]').forEach(el=>el.onclick=()=>{const [id,index]=el.dataset.deleteExercise.split(':');const w=data.plan.find(x=>x.id===id);if(w&&confirm(`„${w.exercises[index]?.name}“ aus der Vorlage entfernen?`)){w.exercises.splice(+index,1);save();render()}});$$('[data-action="catalog-add"]').forEach(el=>el.onclick=()=>catalogEditDialog());$$('[data-catalog-edit]').forEach(el=>el.onclick=()=>catalogEditDialog(el.dataset.catalogEdit));$$('[data-catalog-delete]').forEach(el=>el.onclick=()=>{const name=el.dataset.catalogDelete;if(confirm(`„${name}“ aus dem Übungskatalog entfernen?`)){data.catalog=data.catalog.filter(item=>item.name!==name);save();render()}});$$('[data-filter]').forEach(el=>el.onclick=()=>{historyFilter=el.dataset.filter;render()});$$('[data-stats-exercise]').forEach(el=>el.onchange=()=>{location.hash=`#stats?exercise=${encodeURIComponent(el.value)}`});$$('[data-create-template]').forEach(el=>el.onclick=()=>createTemplateFromHistory(el.dataset.createTemplate));$$('[data-delete-session]').forEach(el=>el.onclick=()=>{if(confirm('Diese Trainingseinheit aus dem Verlauf löschen?')){data.history=data.history.filter(s=>s.id!==el.dataset.deleteSession);save();render()}});$$('[data-action="log-manual"]').forEach(el=>el.onclick=manualDialog);const form=$('#sessionForm');if(form){form.onsubmit=saveSession;form.addEventListener('beforeinput',event=>{if(event.target.name.startsWith('weight-')&&event.data==='.')event.preventDefault()});form.addEventListener('focusin',event=>{if(event.target.name.startsWith('weight-'))event.target.dataset.lastValid=event.target.value});form.addEventListener('input',event=>{const target=event.target;if(target.name.startsWith('weight-'))cleanWeightInput(target);if(target.name.startsWith('reps-')&&target.value){const sec=form.elements[target.name.replace(/^reps-/,'seconds-')];if(sec)sec.value=''}else if(target.name.startsWith('seconds-')&&target.value){const reps=form.elements[target.name.replace(/^seconds-/,'reps-')];if(reps)reps.value=''}});form.addEventListener('input',event=>{const target=event.target,values=sessionDraft.values||(sessionDraft.values={});if(target.name==='templateName'){values.templateName=target.value;persistSessionDraft();return}let match=target.name.match(/^(weight|reps|seconds)-(\d+)-(\d+)$/);if(match){const exercise=sessionDraft.exercises[+match[2]];if(exercise){exercise.draftKey||(exercise.draftKey=crypto.randomUUID());values[`${exercise.draftKey}:${match[3]}:${match[1]}`]=target.value;if(target.value&&(match[1]==='reps'||match[1]==='seconds'))values[`${exercise.draftKey}:${match[3]}:${match[1]==='reps'?'seconds':'reps'}`]='';persistSessionDraft()}return}match=target.name.match(/^note-(\d+)$/);if(match){const exercise=sessionDraft.exercises[+match[1]];if(exercise){exercise.draftKey||(exercise.draftKey=crypto.randomUUID());values[`${exercise.draftKey}:note`]=target.value;persistSessionDraft()}}});const checkbox=$('[name="saveTemplate"]',form);if(checkbox)checkbox.onchange=()=>{$('.template-name-field',form).hidden=!checkbox.checked;if(sessionDraft){sessionDraft.values.saveTemplate=checkbox.checked;persistSessionDraft()}}}$$('[data-export-backup]').forEach(el=>el.onclick=exportData);const importInput=$('#importFile');if(importInput)importInput.onchange=importData;$$('[data-theme-toggle]').forEach(el=>el.onclick=()=>setTheme(themeMode()==='dark'?'light':'dark'));$$('[data-action="settings-cloud-manage"]').forEach(el=>el.onclick=cloudModal);$$('[data-action="settings-cloud-sync"]').forEach(el=>el.onclick=cloudInitialSync);$$('[data-action="settings-cloud-signout"]').forEach(el=>el.onclick=async()=>{persistSessionDraft();stopCloudWatch();await cloudClient.auth.signOut();cloudUser=null;cloudVersion=null;cloudReady=false;activeProfileName='';localStorage.removeItem(ACTIVE_PROFILE_KEY);sessionDraft=loadSessionDraft();data=freshData();localStorage.setItem(KEY,JSON.stringify(data));updateCloudButton();render();toast('Von der Cloud abgemeldet')});const passwordForm=$('#accountPasswordForm');if(passwordForm)passwordForm.onsubmit=async e=>{e.preventDefault();const f=new FormData(passwordForm),status=$('#passwordStatus');if(f.get('password')!==f.get('confirmPassword')){status.textContent='Die Passwörter stimmen nicht überein.';return}try{const {error}=await cloudClient.auth.updateUser({password:f.get('password')});if(error)throw error;passwordForm.reset();status.textContent='Passwort aktualisiert.'}catch(error){status.textContent=error.message||'Passwort konnte nicht geändert werden.'}};$$('[data-action="cancel-session"]').forEach(el=>el.onclick=()=>{persistSessionDraft();location.hash='#home'})}
function modal(content){const d=$('#modal');if(d.open)d.close();delete d.dataset.cloudVersion;d.className='modal';d.innerHTML=content;d.showModal();d.onclick=e=>{if(e.target===d)d.close()};return d}
function workoutDialog(w){const d=modal(`<h2>${w?'Vorlage bearbeiten':'Neue Vorlage'}</h2><p>Lege eine Einheit an, die du bei Bedarf starten und anpassen kannst.</p><form id="workoutForm"><div class="field"><label>Name der Vorlage</label><input name="name" required maxlength="60" value="${esc(w?.name||'')}" placeholder="z. B. Oberkörper"></div><div class="modal-actions"><button type="button" class="button secondary" data-close>Abbrechen</button><button class="button">Speichern</button></div></form>`);$('[data-close]',d).onclick=()=>d.close();$('#workoutForm',d).onsubmit=e=>{e.preventDefault();const name=new FormData(e.target).get('name').trim();if(!name){alert('Bitte gib einen Namen für die Vorlage ein.');return}if(w)w.name=name;else data.plan.push({id:crypto.randomUUID(),name,exercises:[]});save();d.close();render();toast('Vorlage gespeichert')}}
function exerciseDialog(id,index=null){const w=data.plan.find(x=>x.id===id),exercise=index===null?null:w?.exercises[index];if(!w)return;const initial=exercise||{name:'',sets:3,reps:'8–12'};const options=(data.catalog||[]).slice().sort((a,b)=>`${a.group||'Sonstige'} - ${a.name}`.localeCompare(`${b.group||'Sonstige'} - ${b.name}`,'de',{sensitivity:'base'})).map(item=>`<option value="${esc(item.name)}" ${initial.name===item.name?'selected':''}>${esc(item.group||'Sonstige')} - ${esc(item.name)}</option>`).join('');const d=modal(`<h2>${exercise?'Übung bearbeiten':'Aus Katalog hinzufügen'}</h2><p>${esc(w.name)} · letzte Satzwerte werden vorgeschlagen.</p><form id="exerciseForm"><div class="field"><label>Übung aus dem Katalog</label><select name="catalogChoice"><option value="">Übung wählen …</option>${options}<option value="__custom">Eigene Übung …</option></select></div><div class="field"><label>Übungsname</label><input name="name" required maxlength="70" value="${esc(initial.name)}" placeholder="z. B. Bankdrücken"></div><div class="form-grid"><div class="field"><label>Sätze</label><input name="sets" type="number" min="1" max="20" value="${initial.sets}"></div><div class="field"><label>Wiederholungen</label><input name="reps" value="${esc(initial.reps)}" required></div></div><div class="modal-actions"><button type="button" class="button secondary" data-close>Abbrechen</button><button class="button">${exercise?'Speichern':'Zur Vorlage hinzufügen'}</button></div></form>`);$('[data-close]',d).onclick=()=>d.close();const form=$('#exerciseForm',d),choice=$('[name="catalogChoice"]',form);choice.onchange=()=>{const item=catalogItem(choice.value);if(item){$('[name="name"]',form).value=item.name;$('[name="sets"]',form).value=item.sets;$('[name="reps"]',form).value=item.reps}else if(choice.value==='__custom')$('[name="name"]',form).focus()};form.onsubmit=e=>{e.preventDefault();const f=new FormData(form),updated={name:f.get('name').trim(),sets:+f.get('sets')||3,reps:f.get('reps').trim()};if(!updated.name||!updated.reps){alert('Bitte gib einen Übungsnamen und ein Trainingsziel ein.');return}if(index===null)w.exercises.push(updated);else w.exercises[index]=updated;if(!catalogItem(updated.name))data.catalog.push({name:updated.name,group:'Sonstige',sets:updated.sets,reps:updated.reps});save();d.close();render();toast(exercise?'Übung aktualisiert':'Übung hinzugefügt')}}
function catalogEditDialog(name=null){const item=name?catalogItem(name):null;const groupOptions=muscleGroups.map(group=>`<option value="${group}" ${(item?.group||'Sonstige')===group?'selected':''}>${group}</option>`).join('');const d=modal(`<h2>${item?'Katalogübung bearbeiten':'Katalogübung erstellen'}</h2><p>Die letzten Satzwerte werden nach jeder Einheit aktualisiert.</p><form id="catalogForm"><div class="field"><label>Übungsname</label><input name="name" required maxlength="70" value="${esc(item?.name||'')}" placeholder="z. B. Brustpresse"></div><div class="field"><label>Muskelgruppe</label><select name="group" required>${groupOptions}</select></div><div class="form-grid"><div class="field"><label>Sätze</label><input name="sets" type="number" min="1" max="20" value="${item?.sets||3}"></div><div class="field"><label>Wiederholungen</label><input name="reps" required value="${esc(item?.reps||'8–12')}"></div></div><div class="modal-actions"><button type="button" class="button secondary" data-close>Abbrechen</button><button class="button">${item?'Speichern':'Im Katalog ablegen'}</button></div></form>`);$('[data-close]',d).onclick=()=>d.close();$('#catalogForm',d).onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),updated={name:f.get('name').trim(),group:muscleGroups.includes(f.get('group'))?f.get('group'):'Sonstige',sets:+f.get('sets')||3,reps:f.get('reps').trim()};if(!updated.name||!updated.reps){alert('Bitte gib einen Übungsnamen und ein Trainingsziel ein.');return}if(item&&updated.name!==item.name&&catalogItem(updated.name)){alert('Diese Übung ist bereits im Katalog.');return}if(item){const oldName=item.name;const i=data.catalog.indexOf(item);data.catalog[i]=updated;if(oldName!==updated.name){data.plan.forEach(workout=>(workout.exercises||[]).forEach(ex=>{if(ex.name===oldName)ex.name=updated.name}));data.history.forEach(workout=>(workout.exercises||[]).forEach(ex=>{if(ex.name===oldName)ex.name=updated.name}));if(sessionDraft){sessionDraft.exercises.forEach(ex=>{if(ex.name===oldName)ex.name=updated.name});persistSessionDraft()}}}else if(catalogItem(updated.name)){alert('Diese Übung ist bereits im Katalog.');return}else data.catalog.push(updated);save();d.close();render();toast(item?'Katalog aktualisiert':'Übung im Katalog gespeichert')}}
function startFreeSession(){if(sessionDraft?.exercises?.length&&!confirm('Ein begonnenes Training ist zwischengespeichert. Soll es verworfen und ein neues gestartet werden?'))return;sessionDraft={id:crypto.randomUUID(),name:'Spontanes Training',exercises:[],values:{}};persistSessionDraft();location.hash='#session?free=1'}
function freeExerciseDialog(){if(!sessionDraft)startFreeSession();const options=(data.catalog||[]).slice().sort((a,b)=>{const groupA=a.group||'Sonstige',groupB=b.group||'Sonstige';if(groupA==='Sonstige'&&groupB!=='Sonstige')return 1;if(groupB==='Sonstige'&&groupA!=='Sonstige')return -1;return groupA.localeCompare(groupB,'de',{sensitivity:'base'})||a.name.localeCompare(b.name,'de',{sensitivity:'base'})}).map(item=>`<option value="${esc(item.name)}">${esc(item.group||'Sonstige')} - ${esc(item.name)}</option>`).join('');const d=modal(`<h2>Übung hinzufügen</h2><p>Wähle eine Katalogübung oder gib eine eigene Übung ein.</p><form id="freeExerciseForm"><div class="field"><label>Aus dem Katalog</label><select name="choice"><option value="">Übung wählen …</option>${options}<option value="__custom">Eigene Übung …</option></select></div><div class="field"><label>Übungsname</label><input name="name" required placeholder="z. B. Bankdrücken"></div><div class="form-grid"><div class="field"><label>Sätze</label><input name="sets" type="number" min="1" max="20" value="3"></div><div class="field"><label>Wiederholungen</label><input name="reps" required value="8–12"></div></div><div class="modal-actions"><button type="button" class="button secondary" data-close>Abbrechen</button><button class="button">Hinzufügen</button></div></form>`);$('[data-close]',d).onclick=()=>d.close();const form=$('#freeExerciseForm',d);$('[name="choice"]',form).onchange=()=>{const item=catalogItem($('[name="choice"]',form).value);if(item){$('[name="name"]',form).value=item.name;$('[name="sets"]',form).value=item.sets;$('[name="reps"]',form).value=item.reps}else if($('[name="choice"]',form).value==='__custom')$('[name="name"]',form).focus()};form.onsubmit=e=>{e.preventDefault();const f=new FormData(form),exercise={name:f.get('name').trim(),sets:+f.get('sets')||3,reps:f.get('reps').trim()};if(!exercise.name||!exercise.reps){alert('Bitte gib einen Übungsnamen und ein Trainingsziel ein.');return}if(!catalogItem(exercise.name))data.catalog.push({name:exercise.name,group:'Sonstige',sets:exercise.sets,reps:exercise.reps});sessionDraft.exercises.unshift(exercise);persistSessionDraft();save();d.close();render();toast('Übung hinzugefügt')}}
function renderSettings(){const dark=themeMode()==='dark';return `<div class="eyebrow">APP EINRICHTEN</div><div class="heading-row"><div><h1>Settings</h1></div></div><section class="card"><div class="card-head"><h2>Darstellung</h2></div><p class="tiny muted">Wähle ein helles oder dunkles Farbschema.</p><button class="button secondary" type="button" data-theme-toggle>${dark?'☀️ Helles Design aktivieren':'🌙 Dunkles Design aktivieren'}</button></section><section class="card"><div class="card-head"><h2>Login & Cloud-Synchronisierung</h2><span class="pill">${cloudUser?'Verbunden':'Nicht verbunden'}</span></div>${cloudUser?`<div class="settings-account"><div><span class="tiny muted">Profil</span><strong>${esc(activeProfileName||'GrevingFit')}</strong></div><div><span class="tiny muted">E-Mail</span><strong>${esc(cloudUser.email||'')}</strong></div></div><p class="tiny muted">${cloudReady?'Cloud-Synchronisierung aktiv. Änderungen werden automatisch gesichert.':'Cloud-Konto verbunden; Synchronisierung wird vorbereitet.'}</p><div class="split settings-actions"><button class="button" type="button" data-action="settings-cloud-sync">Jetzt synchronisieren</button><button class="button secondary" type="button" data-action="settings-cloud-signout">Abmelden</button></div><details class="settings-password"><summary>Passwort ändern</summary><form id="accountPasswordForm"><div class="field"><label for="newPassword">Neues Passwort</label><input id="newPassword" name="password" type="password" minlength="8" autocomplete="new-password" required></div><div class="field"><label for="confirmPassword">Neues Passwort wiederholen</label><input id="confirmPassword" name="confirmPassword" type="password" minlength="8" autocomplete="new-password" required></div><button class="button secondary" type="submit">Passwort aktualisieren</button><p id="passwordStatus" class="tiny muted" role="status"></p></form></details>`:`<p class="muted tiny">Melde dich mit deinem Profil an oder erstelle das Konto für dein Profil.</p><button class="button" type="button" data-action="settings-cloud-manage">Anmelden oder Konto erstellen</button>`}</section><section class="card"><div class="card-head"><h2>Daten auf diesem Gerät</h2></div><p class="tiny muted">Sichere alle Planungen, Katalogeinträge und den Trainingsverlauf oder stelle ein Backup wieder her.</p><div class="split settings-actions"><button class="button" type="button" data-export-backup>⇅ Sicherung exportieren</button><label class="button secondary" for="importFile">Sicherung importieren</label><input id="importFile" type="file" accept="application/json,.json" hidden></div><p class="tiny muted" style="margin-top:12px">Die Sicherungsdatei enthält Trainingsdaten, aber keine Login-Passwörter.</p></section>`}

function captureSessionForm(form){if(!form||!sessionDraft)return;const values=sessionDraft.values||(sessionDraft.values={});sessionDraft.exercises.forEach((exercise,index)=>{exercise.draftKey||(exercise.draftKey=crypto.randomUUID());for(let setIndex=0;setIndex<(+exercise.sets||1);setIndex++){for(const kind of ['weight','reps','seconds']){const input=form.elements[`${kind}-${index}-${setIndex}`];if(input)values[`${exercise.draftKey}:${setIndex}:${kind}`]=input.value}const done=form.elements[`done-${index}-${setIndex}`];if(done)values[`${exercise.draftKey}:${setIndex}:done`]=done.checked}values[`${exercise.draftKey}:note`]=form.elements[`note-${index}`]?.value||''});const templateName=form.elements.templateName;if(templateName)values.templateName=templateName.value}

function exerciseSetsAreValid(form,index,showMessage=true){const exercise=sessionDraft?.exercises[index];if(!exercise)return false;for(let setIndex=0;setIndex<(+exercise.sets||1);setIndex++){const weight=form.elements[`weight-${index}-${setIndex}`],reps=form.elements[`reps-${index}-${setIndex}`],seconds=form.elements[`seconds-${index}-${setIndex}`];if(weight){cleanWeightInput(weight);if(weight.value&&!/^\d+(,\d{1,2})?$/.test(weight.value)){weight.focus();if(showMessage)alert('Bitte gib das Gewicht mit Komma als Dezimaltrennzeichen ein, z. B. 12,5.');return false}}if(reps?.value&&seconds?.value){reps.focus();if(showMessage)alert('Pro Satz bitte entweder Wiederholungen oder Sekunden eintragen.');return false}if(!weight?.value&&!reps?.value&&!seconds?.value){(reps||weight)?.focus();if(showMessage)alert(`Trage für Satz ${setIndex+1} mindestens einen Wert ein, bevor du ihn abhakst.`);return false}}return true}

function setSessionExerciseStatus(index,status){const form=$('#sessionForm'),exercise=sessionDraft?.exercises[index];if(!form||!exercise)return;captureSessionForm(form);const values=sessionDraft.values||(sessionDraft.values={}),key=exercise.draftKey||(exercise.draftKey=crypto.randomUUID());if(status==='completed'){if(!exerciseSetsAreValid(form,index))return;for(let setIndex=0;setIndex<(+exercise.sets||1);setIndex++)values[`${key}:${setIndex}:done`]=true;exercise.status='completed'}else if(status==='skipped'){exercise.status='skipped'}else if(exercise.status==='completed'){for(let setIndex=0;setIndex<(+exercise.sets||1);setIndex++)values[`${key}:${setIndex}:done`]=false;exercise.status='pending'}else{const allDone=Array.from({length:+exercise.sets||1},(_,setIndex)=>values[`${key}:${setIndex}:done`]===true).every(Boolean);exercise.status=allDone?'completed':'pending'}persistSessionDraft();const top=window.scrollY;render();window.scrollTo(0,top)}

function setSessionSetComplete(index,setIndex,checked){const form=$('#sessionForm'),exercise=sessionDraft?.exercises[index];if(!form||!exercise)return;if(checked){const weight=form.elements[`weight-${index}-${setIndex}`],reps=form.elements[`reps-${index}-${setIndex}`],seconds=form.elements[`seconds-${index}-${setIndex}`];if(weight){cleanWeightInput(weight);if(weight.value&&!/^\d+(,\d{1,2})?$/.test(weight.value)){weight.focus();weight.reportValidity();return false}}if(reps?.value&&seconds?.value){reps.focus();alert('Pro Satz bitte entweder Wiederholungen oder Sekunden eintragen.');return false}if(!weight?.value&&!reps?.value&&!seconds?.value){(reps||weight)?.focus();alert(`Trage für Satz ${setIndex+1} mindestens einen Wert ein, bevor du ihn abhakst.`);return false}}captureSessionForm(form);const values=sessionDraft.values||(sessionDraft.values={}),key=exercise.draftKey||(exercise.draftKey=crypto.randomUUID());values[`${key}:${setIndex}:done`]=checked;const allDone=Array.from({length:+exercise.sets||1},(_,current)=>values[`${key}:${current}:done`]===true).every(Boolean);exercise.status=allDone?'completed':'pending';persistSessionDraft();const top=window.scrollY;render();window.scrollTo(0,top);return true}

function renderSession(){const params=new URLSearchParams(location.hash.split('?')[1]||''),isFree=params.get('free')==='1',id=params.get('id');if(isFree&&!sessionDraft)sessionDraft={id:crypto.randomUUID(),name:'Spontanes Training',exercises:[],values:{}};if(!isFree&&sessionDraft?.sourceWorkoutId!==id){const workout=data.plan.find(item=>item.id===id);if(!workout){location.hash='#plan';return ''}sessionDraft={...structuredClone(workout),exercises:workout.exercises.map(ex=>({...ex,status:'pending'})),sourceWorkoutId:id,values:{}};persistSessionDraft()}const workout=sessionDraft;if(!workout){location.hash='#plan';return ''}const exerciseCards=workout.exercises.map((exercise,index)=>{const previous=lastExerciseUse(exercise.name)?.exercise.sets||[],draftKey=exercise.draftKey||(exercise.draftKey=crypto.randomUUID()),values=workout.values||(workout.values={}),setCount=+exercise.sets||1;let status=exercise.status||'pending';const allDone=Array.from({length:setCount},(_,setIndex)=>values[`${draftKey}:${setIndex}:done`]===true).every(Boolean);if(status!=='skipped')status=allDone?'completed':'pending';exercise.status=status;const sets=Array.from({length:setCount},(_,setIndex)=>{const prior=previous.find(set=>set.setNo===setIndex+1)||previous[setIndex],weight=values[`${draftKey}:${setIndex}:weight`]??formatWeight(prior?.weight??''),done=values[`${draftKey}:${setIndex}:done`]===true;return `<div class="set-row session-set-row"><input name="weight-${index}-${setIndex}" type="text" inputmode="decimal" pattern="[0-9]+(,[0-9]{1,2})?" value="${esc(weight)}" placeholder="kg" aria-label="${esc(exercise.name)} Satz ${setIndex+1} Gewicht"><input name="reps-${index}-${setIndex}" type="number" inputmode="numeric" step="1" min="0" value="${esc(values[`${draftKey}:${setIndex}:reps`]??prior?.reps??'')}" placeholder="Wdh" aria-label="${esc(exercise.name)} Satz ${setIndex+1} Wiederholungen"><input name="seconds-${index}-${setIndex}" type="number" inputmode="numeric" step="1" min="0" value="${esc(values[`${draftKey}:${setIndex}:seconds`]??prior?.seconds??'')}" placeholder="Sek." aria-label="${esc(exercise.name)} Satz ${setIndex+1} Dauer in Sekunden"><label class="set-check"><input name="done-${index}-${setIndex}" type="checkbox" data-set-complete="${index}:${setIndex}" ${done?'checked':''} aria-label="${esc(exercise.name)} Satz ${setIndex+1} fertig"><span aria-hidden="true">✓</span></label></div>`}).join('');return `<section class="card session-exercise" data-status="${status}"><div class="session-exercise-head"><h3><span class="exercise-number">${index+1}</span><span class="session-exercise-title">${esc(exercise.name)}<small class="muted">Ziel ${esc(exercise.reps)}</small></span></h3>${isFree?`<div class="free-exercise-tools"><span class="tiny muted">${setCount} Sätze</span><button class="icon-action" type="button" aria-label="Satzanzahl verringern" title="Satzanzahl verringern" data-free-set-change="${index}:-1">−</button><button class="icon-action" type="button" aria-label="Satzanzahl erhöhen" title="Satzanzahl erhöhen" data-free-set-change="${index}:1">＋</button><button class="icon-action free-exercise-remove" type="button" aria-label="Übung entfernen" title="Übung entfernen" data-free-exercise-delete="${index}">×</button></div>`:''}</div><div class="exercise-status-actions" role="group" aria-label="Status für ${esc(exercise.name)}"><button type="button" class="button small" data-exercise-index="${index}" data-exercise-status="${status==='completed'?'pending':'completed'}" aria-pressed="${status==='completed'}">${status==='completed'?'✓ Fertig':'Fertig'}</button><button type="button" class="button secondary small" data-exercise-index="${index}" data-exercise-status="${status==='skipped'?'pending':'skipped'}" aria-pressed="${status==='skipped'}">${status==='skipped'?'Heute ausgelassen · zurücknehmen':'Heute auslassen'}</button></div>${status==='skipped'?'<p class="tiny muted">Heute ausgelassen. Deine Eingaben bleiben zum Wiederaufnehmen erhalten.</p>':''}<fieldset class="session-set-fields" ${status==='skipped'?'disabled hidden':''}><legend class="sr-only">Satzwerte für ${esc(exercise.name)}</legend><div class="set-row set-row-head" aria-hidden="true"><span>kg</span><span>Wdh.</span><span>Sek.</span><span>✓</span></div>${sets}</fieldset><div class="field" style="margin:12px 0 0"><input name="note-${index}" value="${esc(values[`${draftKey}:note`]||'')}" placeholder="Notiz (optional)" aria-label="Notiz für ${esc(exercise.name)}"></div></section>`}).join('');return `<div class="eyebrow">${isFree?'FREIES TRAINING':'VORLAGEN-TRAINING'} · ${new Date().toLocaleDateString('de-DE',{day:'numeric',month:'long'})}</div><div class="heading-row"><div><h1>${esc(workout.name)}</h1></div>${isFree?'<button class="button secondary small" type="button" data-action="free-add-exercise">＋ Übung</button>':''}</div><form id="sessionForm" data-workout="${esc(workout.id)}" data-free="${isFree}">${workout.exercises.length?exerciseCards:`<section class="card empty"><strong>Noch keine Übungen</strong><p>Füge eine Übung aus dem Katalog hinzu.</p><button class="button secondary" type="button" data-action="free-add-exercise">＋ Übung hinzufügen</button></section>`}${isFree?`<label class="save-template-option"><input type="checkbox" name="saveTemplate" ${workout.values?.saveTemplate?'checked':''}> Als Vorlage für später speichern</label><div class="field template-name-field" ${workout.values?.saveTemplate?'':'hidden'}><label for="templateName">Name der Vorlage</label><input id="templateName" name="templateName" value="${esc(workout.values?.templateName??workout.name)}"></div>`:''}<div class="split session-submit"><button class="button secondary" type="button" data-action="cancel-session">Abbrechen</button><button class="button secondary" type="button" data-action="save-session-draft">Zwischenspeichern</button><button class="button" type="submit">Training speichern ✓</button></div></form>`}

function saveSession(event){event.preventDefault();const form=event.currentTarget,isFree=form.dataset.free==='true',workout=sessionDraft;if(!workout){alert('Diese Trainingseinheit ist nicht mehr verfügbar.');return}if(!workout.exercises.length){alert('Füge mindestens eine Übung hinzu.');return}captureSessionForm(form);const pending=workout.exercises.findIndex(exercise=>!['completed','skipped'].includes(exercise.status));if(pending!==-1){alert('Schließe alle Sätze ab oder wähle für die Übung „Heute auslassen“.');$(`[data-exercise-index="${pending}"]`,form)?.focus();return}for(const input of $$('[name^="weight-"]',form)){if(input.matches(':disabled'))continue;cleanWeightInput(input);if(input.value&&!/^\d+(,\d{1,2})?$/.test(input.value)){input.focus();alert('Bitte gib das Gewicht mit Komma als Dezimaltrennzeichen ein, z. B. 12,5.');return}}const fd=new FormData(form),exercises=workout.exercises.map((exercise,index)=>({name:exercise.name,status:exercise.status,sets:exercise.status==='skipped'?[]:Array.from({length:+exercise.sets||1},(_,setIndex)=>{const rawWeight=fd.get(`weight-${index}-${setIndex}`)||'',reps=fd.get(`reps-${index}-${setIndex}`)||'',seconds=fd.get(`seconds-${index}-${setIndex}`)||'';return {setNo:setIndex+1,weight:rawWeight?Number(String(rawWeight).replace(',','.')):'',reps,seconds,completed:true}}),note:fd.get(`note-${index}`)}));for(const used of exercises){if(used.status==='skipped')continue;let item=catalogItem(used.name);if(!item){item={name:used.name,group:'Sonstige',sets:used.sets.length||3,reps:'8–12'};data.catalog.push(item)}item.sets=used.sets.length||item.sets;const repetitions=used.sets.map(set=>+set.reps||0).filter(Boolean);if(repetitions.length){const low=Math.min(...repetitions),high=Math.max(...repetitions);item.reps=low===high?String(low):`${low}–${high}`}}const today=new Date(),date=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`,templateName=(fd.get('templateName')||'').trim()||workout.name;if(isFree&&fd.get('saveTemplate')==='on'){const templateExercises=workout.exercises.filter(exercise=>exercise.status!=='skipped').map(exercise=>({name:exercise.name,sets:exercise.sets,reps:exercise.reps}));if(templateExercises.length)data.plan.push({id:crypto.randomUUID(),name:templateName,exercises:templateExercises})}data.history.push({id:crypto.randomUUID(),date,name:workout.name,exercises});save();sessionDraft=null;persistSessionDraft();location.hash='#history';toast('Training gespeichert – stark gemacht!')}

function manualDialog(){const choices=data.plan.map(w=>`<option value="${esc(w.name)}">${esc(w.name)}</option>`).join('');const d=modal(`<h2>Einheit eintragen</h2><p>Ergänze auch vergangene Trainings.</p><form id="manualForm"><div class="field"><label>Einheit</label><select name="name">${choices}<option value="Andere">Andere</option></select></div><div class="field"><label>Datum</label><input name="date" type="date" value="${localDateKey(new Date())}" required></div><div class="modal-actions"><button type="button" class="button secondary" data-close>Abbrechen</button><button class="button">Eintragen</button></div></form>`);$('[data-close]',d).onclick=()=>d.close();$('#manualForm',d).onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);data.history.push({id:crypto.randomUUID(),date:f.get('date'),name:f.get('name'),exercises:[]});save();d.close();render();toast('Einheit eingetragen')};}
function exportData(){const backup={app:'GrevingFit',formatVersion:1,exportedAt:new Date().toISOString(),data};const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`grevingfit-backup-${localDateKey(new Date())}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Sicherungsdatei heruntergeladen')}
function isValidFitnessData(state){
 if(!state||!Array.isArray(state.plan)||!Array.isArray(state.history)||('catalog'in state&&!Array.isArray(state.catalog)))return false;
 const text=value=>typeof value==='string'&&value.trim().length>0;
 const target=exercise=>exercise&&text(exercise.name)&&Number.isInteger(Number(exercise.sets))&&Number(exercise.sets)>=1&&Number(exercise.sets)<=20&&(typeof exercise.reps==='string'||typeof exercise.reps==='number');
 const measure=value=>value==null||value===''||(typeof value==='string'||typeof value==='number')&&Number.isFinite(Number(String(value).replace(',','.')))&&Number(String(value).replace(',','.'))>=0;
 const recorded=exercise=>exercise&&text(exercise.name)&&(exercise.status===undefined||['completed','skipped'].includes(exercise.status))&&Array.isArray(exercise.sets)&&exercise.sets.every(set=>set&&typeof set==='object'&&['weight','reps','seconds'].every(key=>measure(set[key])));
 if(state.catalog&&!state.catalog.every(target))return false;
 if(!state.plan.every(workout=>workout&&text(workout.id)&&text(workout.name)&&Array.isArray(workout.exercises)&&workout.exercises.every(target)))return false;
 return state.history.every(workout=>workout&&text(workout.id)&&text(workout.name)&&typeof workout.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(workout.date)&&Number.isFinite(new Date(workout.date+'T12:00:00').getTime())&&localDateKey(new Date(workout.date+'T12:00:00'))===workout.date&&Array.isArray(workout.exercises)&&workout.exercises.every(recorded));
}
function importData(e){const file=e.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(reader.result),incoming=['GrevingFit','CarstenFit'].includes(parsed?.app)&&parsed?.data?parsed.data:parsed;if(!isValidFitnessData(incoming))throw Error();if(!confirm('Der Import ersetzt alle aktuell gespeicherten GrevingFit-Daten auf diesem Gerät. Fortfahren?'))return;data=normalizeData(incoming);save();render();toast('Sicherung auf diesem Gerät wiederhergestellt')}catch{alert('Die Datei ist kein gültiges GrevingFit-Backup. Deine vorhandenen Daten bleiben erhalten.')}finally{e.target.value=''}};reader.readAsText(file)}
localStorage.removeItem('carstenfit-google-client-id-v1');localStorage.removeItem('carstenfit-google-drive-authorized-v1');
for(const key of Object.keys(localStorage))if(key.startsWith('grevingfit-spotify-'))localStorage.removeItem(key);
function render(){const route=getRoute(),allowed=['home','plan','catalog','history','stats','session','settings'],current=allowed.includes(route)?route:'home';$$('#appMenu a').forEach(a=>a.classList.toggle('active',a.dataset.route===current));const app=$('#app');if(current==='settings')app.innerHTML=renderSettings();else if(current==='plan')app.innerHTML=renderPlan();else if(current==='catalog')app.innerHTML=renderCatalog();else if(current==='history')app.innerHTML=renderHistory();else if(current==='stats')app.innerHTML=renderStats();else if(current==='session')app.innerHTML=renderSession();else app.innerHTML=renderHome();$$('.heading-row .subtitle',app).forEach(el=>el.remove());bind()}
document.addEventListener('change',event=>{const target=event.target;if(!target.matches?.('[data-set-complete]'))return;const [exerciseIndex,setIndex]=target.dataset.setComplete.split(':').map(Number);if(!setSessionSetComplete(exerciseIndex,setIndex,target.checked))target.checked=false});
$('#syncBtn').onclick=async()=>{const button=$('#syncBtn');button.classList.add('is-syncing');try{if(cloudUser)await cloudInitialSync();else cloudModal()}finally{button.classList.remove('is-syncing')}};$('#profileMark').onclick=()=>{if(cloudUser)location.hash='#home';else cloudModal()};document.documentElement.dataset.theme=themeMode();startCloud();
const menuToggle=$('#menuToggle'),menu=$('#appMenu');function setMenu(open){menu.hidden=!open;menuToggle.setAttribute('aria-expanded',String(open));menuToggle.setAttribute('aria-label',open?'Menü schließen':'Menü öffnen')}menuToggle.onclick=()=>setMenu(menu.hidden);$$('#appMenu a').forEach(link=>link.onclick=()=>setMenu(false));document.addEventListener('click',e=>{if(!menu.hidden&&!menu.contains(e.target)&&!menuToggle.contains(e.target))setMenu(false)});document.addEventListener('keydown',e=>{if(e.key==='Escape')setMenu(false)});
let lastPageRoute=getRoute();
function animatePageChange(){const route=getRoute();if(route===lastPageRoute)return;lastPageRoute=route;const app=$('#app');app.classList.remove('page-transition-in');void app.offsetWidth;app.classList.add('page-transition-in');app.addEventListener('animationend',()=>app.classList.remove('page-transition-in'),{once:true})}
window.addEventListener('hashchange',()=>{render();animatePageChange();if(!$('#appMenu').hidden)setMenu(false)});render();
window.addEventListener('online',()=>{if(cloudUser)cloudInitialSync()});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&cloudUser)cloudInitialSync()});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#installBtn').hidden=false});$('#installBtn').onclick=async()=>{if(!installPrompt)return;installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$('#installBtn').hidden=true};
